from __future__ import annotations

from fastapi.responses import HTMLResponse


def analysis_page() -> HTMLResponse:
    return HTMLResponse(
        r'''<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Nmap Terrain Analyzer · Analyze Results</title>
  <style>
    :root{color-scheme:dark;--bg:#091016;--panel:#111c25;--line:#263f49;--text:#edf6fb;--muted:#9eb0b8;--accent:#53d1b6;--blue:#64a9ff;--good:#61d095;--warn:#ffc66d;--bad:#ff837a}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top right,#102c35,#091016 44%);color:var(--text);font:14px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}header,main{max-width:1180px;margin:auto}header{padding:26px 0 20px;border-bottom:1px solid var(--line)}h1{margin:0 0 4px;font-size:29px}h2{margin:0 0 9px;font-size:19px}h3{margin:20px 0 8px}.sub,.hint,.meta,.empty{color:var(--muted)}.eyebrow{color:var(--accent);font-weight:800;letter-spacing:.08em;text-transform:uppercase;font-size:11px}.nav{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}.nav a{border:1px solid #315264;background:#142d38;color:#b9cadc;border-radius:7px;padding:9px 13px;text-decoration:none;font-weight:700}.nav a.active{background:var(--accent);border-color:var(--accent);color:#07171b}main{padding:24px 0 60px}.panel{background:rgba(17,28,37,.95);border:1px solid var(--line);border-radius:13px;padding:20px;box-shadow:0 12px 38px #0004;margin-bottom:18px}.grid{display:grid;grid-template-columns:1fr 1.4fr;gap:18px;align-items:start}.actions{display:flex;flex-wrap:wrap;gap:9px;align-items:center;margin-top:13px}button,.button-link{border:1px solid #3b6f91;background:#174665;color:#fff;border-radius:7px;padding:9px 12px;font:inherit;font-weight:750;cursor:pointer;text-decoration:none;display:inline-block}button.secondary,.button-link.secondary{background:transparent;border-color:#49617d}button:disabled{opacity:.5;cursor:not-allowed}input,select{width:100%;background:#0b141b;border:1px solid #344754;color:var(--text);border-radius:8px;padding:10px 11px;font:inherit}label{display:block;color:#bed0da;font-size:12px;font-weight:700;margin:5px 0}.status{min-height:23px;margin-top:10px;color:var(--muted)}.status.good{color:var(--good)}.status.bad{color:var(--bad)}.status.warn{color:var(--warn)}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin:14px 0}.card{padding:12px;background:#0b171f;border:1px solid var(--line);border-radius:9px}.card b{display:block;font-size:22px;color:var(--blue)}.coverage{padding:13px;background:#0b171f;border:1px solid #315264;border-radius:9px;margin:12px 0}.filterbar{display:grid;grid-template-columns:2fr 1fr;gap:12px;margin:18px 0}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;vertical-align:top;padding:8px;border-bottom:1px solid var(--line)}th{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.05em}td{font-size:12px}.history-table{min-width:800px}.port-chip{display:block;padding:5px 7px;margin-bottom:4px;border-left:3px solid transparent;border-radius:5px}.port-chip.outlier{background:#4a3218;border-left-color:var(--warn);color:#ffe1ad}.outlier-tag{display:inline-block;margin-left:7px;padding:2px 5px;border-radius:99px;background:var(--warn);color:#291906;font-size:10px;font-weight:900;text-transform:uppercase}.group-label{color:var(--blue);font-weight:700}.outlier-group{margin:10px 0;padding:14px;background:#0b171f;border:1px solid var(--line);border-radius:9px}.result-box{margin-top:12px;padding:12px;background:#0b171f;border:1px solid var(--line);border-radius:9px}.result-box:empty{display:none}code{color:#9cd4ff}.hidden{display:none!important}@media(max-width:1200px){header,main{padding-left:4vw;padding-right:4vw}}@media(max-width:820px){.grid,.filterbar{grid-template-columns:1fr}.cards{grid-template-columns:1fr 1fr}}
    header{position:sticky;top:0;z-index:100;padding-top:16px;padding-bottom:14px;background:rgba(9,16,22,.96);backdrop-filter:blur(14px);box-shadow:0 9px 24px #0006}header h1{font-size:26px}.nav{margin-top:12px}
  </style>
</head>
<body>
  <header><div class="eyebrow">One analysis pipeline</div><h1>Analyze Nmap Results</h1><p class="sub">New uploads and historical scans use the same complete analysis view.</p><nav class="nav" aria-label="Primary"><a href="/scans">Nmap Scans</a><a class="active" href="/analysis" aria-current="page">Analyze Results</a><a href="/device-config">Device Configurations</a><a href="/network-map">Network Map</a></nav></header>
  <main>
    <div class="grid">
      <section class="panel"><h2>Import Nmap XML</h2><form id="xmlForm"><label for="xmlFile">Nmap XML result</label><input id="xmlFile" type="file" accept=".xml,text/xml,application/xml" required><p class="hint">The original file and SHA-256 hash are retained.</p><div class="actions"><button type="submit">Import &amp; analyze</button></div><div id="xmlStatus" class="status" role="status"></div></form></section>
      <section class="panel"><div class="actions" style="justify-content:space-between;margin-top:0"><div><h2>Previous scans</h2><p class="hint">Open historical scans in the same polished analysis view, or select two to compare.</p></div><button id="historyRefresh" class="secondary">Refresh</button></div><div id="historyStatus" class="status"></div><div id="history" class="meta">Loading…</div><div class="actions"><button id="compare" disabled>Compare selected scans</button></div><div id="compareResult" class="result-box"></div></section>
    </div>
    <section id="analysisPanel" class="panel hidden"><div id="analysisTitle"></div><div id="results"></div><div id="autoCompareResult" class="result-box"></div></section>
  </main>
<script>
const $=id=>document.getElementById(id),qa=s=>[...document.querySelectorAll(s)],esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),csvCell=value=>'"'+String(value??'').replace(/"/g,'""')+'"';
let historyItems=[],currentAnalysis=null,currentLabel='nmap-terrain-results';
function setStatus(id,message,kind=''){const node=$(id);node.textContent=message;node.className='status '+kind}
function protocolLabel(coverage){return(coverage?.protocols||[]).join(' + ')||'Not recorded'}
function coverageText(coverage){if(!coverage)return'Coverage metadata unavailable';const scans=(coverage.scan_types||[]).map(item=>`${item.protocol||'?'} ${item.service_count||0} services`).join(' · '),path=coverage.traceroute?' · traceroute paths collected':'';return `${protocolLabel(coverage)}${scans?' · '+scans:''} · DNS lookups ${coverage.dns_resolution_disabled?'disabled (-n)':'not confirmed'}${path}`}
function downloadCsv(filename,header,records){const csv=[header,...records].map(row=>row.map(csvCell).join(',')).join('\r\n')+'\r\n',blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=filename;link.click();URL.revokeObjectURL(link.href)}
function exportHosts(){const hosts=qa('.host-row').filter(row=>row.style.display!=='none').map(row=>currentAnalysis.hosts[Number(row.dataset.index)]),header=['IP','Hostname','Host state','MAC','MAC vendor','Detected OS','OS family','OS generation','OS role group','Classification basis','Outlying ports','Open services'],records=hosts.map(h=>[h.ip,h.hostname,h.state,h.mac,h.vendor,h.os,h.os_family,h.os_generation,h.os_group,h.classification_basis,(h.ports||[]).filter(p=>p.outlier).map(p=>`${p.port}/${p.protocol}`).join('; '),(h.ports||[]).map(p=>`${p.port}/${p.protocol} ${p.service||''}${p.product?' '+p.product:''}${p.version?' '+p.version:''}`).join('; ')]);downloadCsv(`${currentLabel}-host-summary.csv`,header,records)}
function exportPorts(){const visible=new Set(qa('.host-row').filter(row=>row.style.display!=='none').map(row=>Number(row.dataset.index))),header=['IP','Hostname','Host state','MAC','MAC vendor','Protocol','Port','Port state','Reason','Service','Product','Version','Detected OS','OS role group','Outlier'],records=[];(currentAnalysis.hosts||[]).forEach((h,index)=>{if(!visible.has(index))return;(h.ports||[]).forEach(p=>records.push([h.ip,h.hostname,h.state,h.mac,h.vendor,p.protocol,p.port,p.state||'open',p.reason,p.service,p.product,p.version,h.os,h.os_group,p.outlier?'yes':'no']))});downloadCsv(`${currentLabel}-port-level.csv`,header,records)}
function renderAnalysis(a,context={}){currentAnalysis=a;currentLabel=String(context.display_name||context.filename||'nmap-terrain-results').replace(/[^A-Za-z0-9._()-]+/g,'_');$('analysisPanel').classList.remove('hidden');$('autoCompareResult').innerHTML='';$('analysisTitle').innerHTML=`<h2>${esc(context.display_name||context.filename||'Nmap analysis')}</h2><p class="meta">${esc(context.subtitle||'Complete retained analysis')}</p>`;const outlierTotal=(a.os_groups||[]).reduce((n,g)=>n+(g.outlying_ports||[]).length,0),options=(a.os_groups||[]).map(g=>`<option value="${esc(g.name)}">${esc(g.name)} (${g.host_count})</option>`).join(''),groups=(a.os_groups||[]).map(g=>`<section class="outlier-group" data-outlier-group="${esc(g.name)}"><h3>${esc(g.name)} · ${g.host_count} host${g.host_count===1?'':'s'}</h3>${g.host_count<2?'<p class="empty">At least two hosts are needed to identify outliers.</p>':(g.outlying_ports||[]).length?`<div class="table-wrap"><table><thead><tr><th>Outlying port</th><th>Service</th><th>Seen on</th><th>Affected hosts</th></tr></thead><tbody>${g.outlying_ports.map(p=>`<tr><td>${esc(p.port)}/${esc(p.protocol)}</td><td>${esc(p.service)}${p.product?' · '+esc(p.product):''}</td><td>${p.host_count} of ${p.group_host_count} (${p.prevalence_percent}%)</td><td>${p.hosts.map(esc).join('<br>')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">No statistical port outliers in this group.</p>'}</section>`).join(''),rows=(a.hosts||[]).map((h,index)=>{const search=[h.ip,h.hostname,h.mac,h.vendor,h.os,h.os_family,h.os_generation,h.device_type,h.os_group,...(h.ports||[]).flatMap(p=>[p.port,p.protocol,p.service,p.product,p.version])].join(' ').toLowerCase(),ports=(h.ports||[]).map(p=>`<span class="port-chip${p.outlier?' outlier':''}">${esc(p.port)}/${esc(p.protocol)} ${esc(p.service)}${p.product?' · '+esc(p.product):''}${p.version?' '+esc(p.version):''}${p.outlier?'<span class="outlier-tag">Outlier</span>':''}</span>`).join('')||'None reported';return`<tr class="host-row" data-index="${index}" data-group="${esc(h.os_group)}" data-search="${esc(search)}"><td><strong>${esc(h.ip||'—')}</strong><br><span class="meta">${esc(h.hostname||'')}</span></td><td>${esc(h.state)}</td><td>${esc(h.mac||'—')}<br><span class="meta">${esc(h.vendor||'')}</span></td><td>${esc(h.os||'Unknown')}<br><span class="group-label">${esc(h.os_group)}</span><br><span class="hint">${esc(h.classification_basis)}</span></td><td>${ports}</td></tr>`}).join('');$('results').innerHTML=`<div class="cards"><div class="card"><b id="visibleHosts">${a.host_count||0}</b>matching hosts</div><div class="card"><b>${a.up_count||0}</b>hosts up</div><div class="card"><b>${a.mac_count||0}</b>MAC addresses</div><div class="card"><b>${outlierTotal}</b>outlying ports</div></div><div class="coverage"><strong>Scan coverage</strong><br>${esc(coverageText(a.coverage))}${a.started?`<br><span class="meta">Started ${esc(a.started)}${a.finished?' · Finished '+esc(a.finished):''}</span>`:''}</div><div class="filterbar"><div><label for="hostSearch">Search results</label><input id="hostSearch" type="search" placeholder="IP, hostname, MAC, OS, service, product, or port"></div><div><label for="osFilter">OS / role group</label><select id="osFilter"><option value="">All OS groups</option>${options}</select></div></div><div class="actions"><button id="exportHosts" class="secondary">Export host summary CSV</button><button id="exportPorts">Export port-level CSV</button></div><h3>Outlying ports by OS type</h3><div id="outlierGroups">${groups||'<p class="empty">No OS groups were detected.</p>'}</div><h3>Host inventory</h3><div class="table-wrap"><table><thead><tr><th>IP / hostname</th><th>State</th><th>MAC / vendor</th><th>OS / peer group</th><th>Open services</th></tr></thead><tbody>${rows}</tbody></table></div>`;const apply=()=>{const term=$('hostSearch').value.trim().toLowerCase(),group=$('osFilter').value;let visible=0;qa('.host-row').forEach(row=>{const show=(!group||row.dataset.group===group)&&(!term||row.dataset.search.includes(term));row.style.display=show?'':'none';if(show)visible++});$('visibleHosts').textContent=visible;qa('.outlier-group').forEach(card=>card.style.display=(!group||card.dataset.outlierGroup===group)?'':'none')};$('hostSearch').oninput=apply;$('osFilter').onchange=apply;$('exportHosts').onclick=exportHosts;$('exportPorts').onclick=exportPorts;$('analysisPanel').scrollIntoView({behavior:'smooth',block:'start'})}
function renderHistory(){if(!historyItems.length){$('history').innerHTML='<div class="empty">No imported Nmap scans have been retained.</div>';$('compare').disabled=true;return}$('history').innerHTML=`<div class="table-wrap"><table class="history-table"><thead><tr><th>Select</th><th>Scan</th><th>Imported</th><th>Coverage</th><th>Identity</th><th>Actions</th></tr></thead><tbody>${historyItems.map(item=>`<tr><td><input type="checkbox" data-select="${esc(item.sha256)}" aria-label="Select ${esc(item.display_name||item.filename)}"></td><td><strong>${esc(item.display_name||item.filename)}</strong><br><span class="meta">${esc(item.filename)} · ${esc(item.sha256.slice(0,12))}</span></td><td>${esc(item.imported_at)}</td><td>${esc(coverageText(item.summary?.coverage))}<br><span class="meta">${Number(item.summary?.up_count||0)} up / ${Number(item.summary?.host_count||0)} parsed</span></td><td>${Number(item.summary?.mac_count||0)} MAC addresses<br>${Number(item.summary?.os_group_count||0)} OS groups</td><td><button data-open="${esc(item.sha256)}">Open &amp; analyze</button> <a class="button-link secondary" href="/api/imports/${encodeURIComponent(item.sha256)}/raw">Raw XML</a></td></tr>`).join('')}</tbody></table></div>`;qa('[data-select]').forEach(box=>box.onchange=()=>{$('compare').disabled=qa('[data-select]:checked').length!==2});qa('[data-open]').forEach(button=>button.onclick=()=>openHistory(button.dataset.open))}
async function loadHistory(){setStatus('historyStatus','Loading…');try{const r=await fetch('/api/imports?limit=100'),data=await r.json();if(!r.ok)throw new Error(data.detail||'History request failed');historyItems=data||[];renderHistory();setStatus('historyStatus',`${historyItems.length} retained scan${historyItems.length===1?'':'s'}`,'good')}catch(error){setStatus('historyStatus',error.message,'bad')}}
async function openHistory(sha){setStatus('historyStatus','Opening full analysis…');try{const r=await fetch(`/api/imports/${encodeURIComponent(sha)}`),item=await r.json();if(!r.ok)throw new Error(item.detail||'Analysis could not be opened');renderAnalysis(item.analysis||{},{display_name:item.display_name||item.filename,filename:item.filename,subtitle:`Imported ${item.imported_at} · historical analysis`});setStatus('historyStatus','Historical scan opened in the full analysis view.','good')}catch(error){setStatus('historyStatus',error.message,'bad')}}
function comparisonHostName(host){return host.hostname||host.ip||host.key||'Unknown host'}
function renderAutomaticComparison(result){const target=$('autoCompareResult');if(result.status!=='baseline_found'){target.innerHTML=`<h3>Automatic same-scope comparison</h3><p class="meta">${esc(result.message||'No compatible baseline is available.')}</p>`;return}const summary=result.summary||{},warnings=result.coverage_warnings||[],changed=result.hosts_changed||[],scope=result.current?.scope||{},warningHtml=warnings.length?`<div class="coverage"><strong>Coverage warning</strong><ul>${warnings.map(item=>`<li>${esc(item)}</li>`).join('')}</ul><span class="meta">Host changes are still shown, but port and service differences should be interpreted only across overlapping coverage.</span></div>`:'<p class="status good">Coverage matches the selected baseline.</p>';target.innerHTML=`<h3>Automatic same-scope comparison</h3><p class="meta">${esc(result.baseline?.display_name||'Previous scan')} → ${esc(result.current?.display_name||'Current scan')} · ${Number(scope.address_count||0).toLocaleString()} effective addresses · ${Number(result.current?.chunk_count||1)} chunk${Number(result.current?.chunk_count||1)===1?'':'s'}</p>${warningHtml}<div class="cards"><div class="card"><b>${summary.hosts_added||0}</b>hosts added</div><div class="card"><b>${summary.hosts_removed||0}</b>hosts removed</div><div class="card"><b>${summary.hosts_changed||0}</b>hosts changed</div><div class="card"><b>${summary.route_changes||0}</b>route changes</div></div>${(result.hosts_added||[]).length?`<h3>New hosts</h3><ul>${result.hosts_added.map(host=>`<li>${esc(comparisonHostName(host))}${host.ip?` · <code>${esc(host.ip)}</code>`:''}</li>`).join('')}</ul>`:''}${(result.hosts_removed||[]).length?`<h3>Missing hosts</h3><ul>${result.hosts_removed.map(host=>`<li>${esc(comparisonHostName(host))}${host.ip?` · <code>${esc(host.ip)}</code>`:''}</li>`).join('')}</ul>`:''}${changed.length?`<h3>Changed hosts</h3><ul>${changed.map(host=>`<li><strong>${esc(comparisonHostName(host))}</strong> · ${(host.added_ports||[]).length} ports opened · ${(host.removed_ports||[]).length} ports no longer open · ${(host.service_changes||[]).length} service changes · ${Object.keys(host.identity_changes||{}).length} identity changes${host.route_change?' · route changed':''}</li>`).join('')}</ul>`:''}${!summary.hosts_added&&!summary.hosts_removed&&!summary.hosts_changed?'<p class="status good">No host, port, service, identity, MAC, or route changes were detected.</p>':''}`}
async function loadAutomaticComparison(runId){const target=$('autoCompareResult');target.innerHTML='<h3>Automatic same-scope comparison</h3><p class="meta">Finding the latest completed scan with the same effective target scope…</p>';try{const response=await fetch(`/api/scan-runs/${encodeURIComponent(runId)}/comparison`),result=await response.json();if(!response.ok)throw new Error(result.detail||'Automatic comparison failed');renderAutomaticComparison(result)}catch(error){target.innerHTML=`<h3>Automatic same-scope comparison</h3><p class="status bad">${esc(error.message)}</p>`}}
async function openRun(runId){setStatus('xmlStatus','Opening automated scan analysis…');try{const r=await fetch(`/api/scan-runs/${encodeURIComponent(runId)}/analysis`),item=await r.json();if(!r.ok)throw new Error(item.detail||'Run analysis could not be opened');renderAnalysis(item.analysis||{},{display_name:item.display_name,subtitle:`Automated scan · ${item.metadata?.created_at||''} · ${item.metadata?.profile||''} v${item.metadata?.profile_version||''}`});setStatus('xmlStatus','Automated scan opened in the full analysis view.','good');await loadAutomaticComparison(runId)}catch(error){setStatus('xmlStatus',error.message,'bad')}}
async function compare(){const selected=qa('[data-select]:checked').map(box=>box.dataset.select);if(selected.length!==2)return;const target=$('compareResult');target.innerHTML='<span class="meta">Comparing…</span>';try{const r=await fetch(`/api/imports/compare?first=${encodeURIComponent(selected[0])}&second=${encodeURIComponent(selected[1])}`),result=await r.json();if(!r.ok)throw new Error(result.detail||'Comparison failed');const s=result.summary||{},row=(title,items,render)=>items.length?`<h3>${title} (${items.length})</h3><ul>${items.map(render).join('')}</ul>`:'';target.innerHTML=`<h3>Scan comparison</h3><p class="meta">${esc(result.before.filename)} → ${esc(result.after.filename)}</p><p>${s.hosts_added||0} hosts added · ${s.hosts_removed||0} removed · ${s.hosts_changed||0} changed</p>${row('Hosts added',result.hosts_added||[],h=>`<li>${esc(h.hostname||h.ip||h.key)}</li>`)}${row('Hosts removed',result.hosts_removed||[],h=>`<li>${esc(h.hostname||h.ip||h.key)}</li>`)}${row('Hosts changed',result.hosts_changed||[],h=>`<li><strong>${esc(h.ip||h.key)}</strong> · ${(h.added_ports||[]).length} ports added · ${(h.removed_ports||[]).length} removed · ${(h.service_changes||[]).length} service changes · ${Object.keys(h.identity_changes||{}).length} identity changes</li>`)}`;}catch(error){target.innerHTML=`<span class="status bad">${esc(error.message)}</span>`}}
$('xmlForm').onsubmit=async event=>{event.preventDefault();const file=$('xmlFile').files[0];if(!file)return;setStatus('xmlStatus','Preserving and analyzing the original XML…');try{const form=new FormData();form.append('file',file);const r=await fetch('/api/import',{method:'POST',body:form}),data=await r.json();if(!r.ok)throw new Error(data.detail||'Import failed');renderAnalysis(data.analysis,{display_name:data.metadata?.display_name||file.name,filename:file.name,subtitle:`${data.duplicate?'Duplicate recognized':'Original preserved'} · SHA-256 ${data.sha256}`});setStatus('xmlStatus','Analysis complete.','good');await loadHistory()}catch(error){setStatus('xmlStatus',error.message,'bad')}};
$('historyRefresh').onclick=loadHistory;$('compare').onclick=compare;loadHistory();const runId=new URLSearchParams(location.search).get('run');if(runId)openRun(runId);
</script>
</body></html>'''
    )
